def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find full divider lines.
    div_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    div_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    div_rows = [r for r in div_rows if grid[r][0] != 0]
    div_cols = [c for c in div_cols if grid[0][c] != 0]

    if div_rows and div_cols:
        dr, dc = div_rows[0], div_cols[0]
        color = grid[dr][0]
        for r in range(h):
            for c in range(w):
                if r == dr or c == dc:
                    out[r][c] = color
                else:
                    out[r][c] = grid[r % (dr + 1) if r > dr else r][c % (dc + 1) if c > dc else c]
        return out

    if div_cols:
        dc = div_cols[0]
        period = dc + 1
        # The patterned tile is the block immediately to the right of the divider.
        for r in range(h):
            for c in range(w):
                if c % period == dc:
                    out[r][c] = grid[r][dc]
                else:
                    src = dc + 1 + ((c - (dc + 1)) % dc)
                    if src < w:
                        out[r][c] = grid[r][src]
                    else:
                        out[r][c] = grid[r][c % period]
        return out

    return out
